import{_ as o,o as a,c as n,a6 as c}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{},"headers":[],"relativePath":"js-gui-course/about.md","filePath":"js-gui-course/docs/about.md"}'),t={name:"js-gui-course/about.md"};function p(d,e,s,r,i,l){return a(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p>这门课回答一个问题：<strong>JS 是怎么接入原生 GUI 的</strong>——Electron 那类桌面端背后的原理，而不是框架 API 的用法。</p><p>输入是主题句「JS 接入 GUI 的原理（Electron 式桌面端），要原理不要调包」。全书 13 章（3 原理 + 10 实验），围绕一个伴生实验场展开：你会在 <code>companion/</code> 里从零构建一个 mini-Electron 内核——模拟原生层（事件队列、runLoop、窗口管理器）、嵌入运行时、binding 桥、异步任务队列、IPC 通道（invoke/handle 与 send/on）、事件分发，最终用 <code>createApp</code> 组装出「点按钮改状态刷新界面」的完整回路，55 条原理断言全程背书。真机篇两章带你走出模拟：手工组装 WebAssembly 模块真的跨一次语言边界，再把内核接上真实键盘跑可交互终端 App，并用 Bun FFI 直调 user32.dll 弹出一扇如假包换的系统窗口。</p><p>跑法：</p><ul><li>聚合站预览：项目根目录 <code>pnpm dev</code>，从课程中心进入本课。</li><li>单课预览：<code>cd courses/js-gui-course &amp;&amp; pnpm install &amp;&amp; pnpm docs:dev</code>。</li><li>实验场门槛：<code>cd companion &amp;&amp; npm install &amp;&amp; npm test</code>（另有 <code>npm run typecheck</code>）。</li><li>可运行 demo：<code>npm run demo</code>（+ 加一、q 退出）；<code>bun src/app/native-window.mjs --msgbox</code> 真系统弹窗。</li></ul>',5)])])}const _=o(t,[["render",p]]);export{u as __pageData,_ as default};
